args.content:
let products = [
  { id: 1, name: 'Laptop', price: 999, inventory: 120, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 84, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 0, available: false },
  { id: 4, name: 'Headphones', price: 199, inventory: 210, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 47, available: true },
]

let lastSyncedAt = null

export async function getCatalogFromDb() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return { products, lastSyncedAt }
}

export async function syncProductsFromErp() {
  await new Promise((resolve) => setTimeout(resolve, 3000))
  products = products.map((p) => ({
    ...p,
    price: Math.max(1, Math.round(p.price * (0.9 + Math.random() * 0.2))),
    inventory: Math.floor(Math.random() * 250),
    available: Math.random() > 0.1,
  }))
  lastSyncedAt = new Date().toISOString()
}

